'use strict';
window.WordWeb=(()=>{
 // Each web is authored from the learner's supplied book image; this vocabulary stays outside the daily word pool.
 const n=(id,korean,meaning,answers,children=[])=>({id,korean,meaning,answers,children});
 const webs=[{id:'korea',title:'한국 · Korea',roots:[{id:'han',reading:'한',hanja:'韓',meaning:'Korea',children:[
 n('republic','대한민국','the Republic of Korea',['republic of korea','south korea','korea'],[n('college','대학','college / university',['college','university']),n('biggest','최대','the biggest / maximum',['biggest','largest','maximum']),n('most','대부분','most / the greater part',['most','most of','majority','the majority'])]),
 n('hanbok','한복','hanbok / traditional Korean clothing',['hanbok','traditional korean clothing','korean traditional clothing'],[n('uniform','교복','school uniform',['school uniform','uniform']),n('swimsuit','수영복','swimsuit / swimwear',['swimsuit','swimwear','swimming suit']),n('sportswear','운동복','sportswear / workout clothes',['sportswear','workout clothes','gym clothes','gym clothing'])]),
 n('wave','한류','the Korean wave / spread of Korean pop culture',['korean wave','hallyu','spread of korean pop culture'],[n('exchange','교류','exchange / interaction',['exchange','interaction']),n('upper','상류','upper class / upstream',['upper class','upstream']),n('mainstream','주류','mainstream',['mainstream'])])]},
 {id:'guk',reading:'국',hanja:'國',meaning:'country',children:[
 n('korean','한국어','the Korean language',['korean','korean language'],[n('vocabulary','단어','word / vocabulary item',['word','vocabulary','vocabulary item']),n('language','언어','language',['language']),n('study','어학','language study',['language study','language learning','study of languages'])]),
 n('foreign','외국','foreign country',['foreign country','foreign countries','abroad'],[n('outing','외출','going out / an outing',['going out','going outside','outing']),n('overseas','해외','overseas / abroad',['overseas','abroad']),n('diplomacy','외교','diplomacy',['diplomacy','foreign relations'])]),
 n('domestic','국내','domestic / within the country',['domestic','within the country','in the country'],[n('content','내용','content / contents',['content','contents']),n('indoors','실내','indoors / inside a room',['indoors','indoor','inside','inside a room']),n('downtown','시내','downtown / in the city',['downtown','city center','city centre','in the city'])])]}]}];
 let selected='korea',opened=new Set();
 const allNodes=web=>web.roots.flatMap(r=>r.children.flatMap(node=>[node,...node.children]));
 function normalize(raw){const valid=new Set(webs.flatMap(w=>allNodes(w).map(n=>w.id+':'+n.id)));return Object.fromEntries(Object.entries(raw||{}).filter(([id,p])=>valid.has(id)&&p&&typeof p==='object').map(([id,p])=>[id,{attempts:Number.isSafeInteger(p.attempts)&&p.attempts>=0?p.attempts:0,correct:!!p.correct,seen:!!p.seen,lastAt:typeof p.lastAt==='string'?p.lastAt:''}]))}
 const clean=s=>s.toLocaleLowerCase().replace(/^(the|a|an)\s+/,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
 const accepts=(node,answer)=>node.answers.some(a=>clean(a)===clean(answer));
 function result(node,answer,reveal=false){state.wordWebProgress=normalize(state.wordWebProgress);const id=selected+':'+node.id,old=state.wordWebProgress[id]||{attempts:0,correct:false},correct=!reveal&&accepts(node,answer);state.wordWebProgress[id]={attempts:old.attempts+(reveal?0:1),correct,seen:true,lastAt:new Date().toISOString()};save();return correct}
 function guess(id){const web=webs.find(w=>w.id===selected),node=allNodes(web).find(n=>n.id===id),progress=state.wordWebProgress?.[selected+':'+id];showDialog(`<h2 lang="ko" translate="no">${e(node.korean)}</h2><form id="webGuessForm"><label for="webGuess">Guess the English meaning</label><input id="webGuess" autocomplete="off" required><div class="hub-actions"><button class="btn primary" type="submit">Check meaning</button><button class="small-btn" type="button" id="webReveal">Reveal answer</button></div></form><div id="webAnswer" role="status"></div>`);const finish=(answer,reveal)=>{const correct=result(node,answer,reveal);$('#webAnswer').innerHTML=`<strong>${reveal?'Answer':correct?'Correct!':'Keep practising'}</strong><p translate="no">${e(node.meaning)}</p><button class="btn primary" id="webContinue">${node.children.length?'Explore connected words':'Continue'}</button>`;$('#webContinue').onclick=()=>{$('#dialog').close();render()};$('#webGuessForm').hidden=true};$('#webGuessForm').onsubmit=ev=>{ev.preventDefault();finish($('#webGuess').value,false)};$('#webReveal').onclick=()=>finish('',true)}
 function nodeMarkup(node){const p=state.wordWebProgress?.[selected+':'+node.id];return`<div class="web-node-group"><button class="web-word ${p?.seen?'seen':''} ${p?.correct?'known':''}" data-web-word="${node.id}" aria-label="Guess ${e(node.korean)}"><span lang="ko" translate="no">${e(node.korean)}</span>${p?.seen?`<small translate="no">${e(node.meaning)}</small>`:'<small>Guess meaning</small>'}${p?.correct?'<span class="web-tick">✓</span>':''}</button>${node.children.length&&p?.seen?`<div class="web-leaves">${node.children.map(nodeMarkup).join('')}</div>`:''}</div>`}
 function render(){state.wordWebProgress=normalize(state.wordWebProgress);const web=webs.find(w=>w.id===selected)||webs[0],nodes=allNodes(web),known=nodes.filter(n=>state.wordWebProgress[web.id+':'+n.id]?.correct).length;$('#hubBody').innerHTML=`<div class="web-toolbar"><label class="session-field">Choose a word web<select id="wordWebSelect">${webs.map(w=>`<option value="${w.id}" ${w.id===selected?'selected':''}>${e(w.title)}</option>`).join('')}</select></label><strong>${known} / ${nodes.length} recalled</strong><button class="small-btn" id="collapseWeb">Collapse branches</button></div><div class="word-web"><div class="web-roots">${web.roots.map(r=>`<button class="web-root ${opened.has(r.id)?'selected':''}" data-web-root="${r.id}" aria-expanded="${opened.has(r.id)}"><strong lang="ko">${r.reading}</strong>${opened.has(r.id)?`<small>${r.hanja} · ${r.meaning}</small>`:'<small>Explore →</small>'}</button>`).join('')}</div>${!opened.size?'<p class="web-prompt">Choose a circle to start.</p>':''}<div class="web-root-branches">${web.roots.filter(r=>opened.has(r.id)).map(r=>`<section class="web-root-branch"><h2 lang="ko">${r.reading} <small>${r.hanja} · ${r.meaning}</small></h2><div class="web-branches">${r.children.map(nodeMarkup).join('')}</div></section>`).join('')}</div></div>`;$('#wordWebSelect').onchange=ev=>{selected=ev.target.value;opened=new Set();render()};$('#collapseWeb').onclick=()=>{opened.clear();render()};document.querySelectorAll('[data-web-root]').forEach(b=>b.onclick=()=>{const id=b.dataset.webRoot;opened.has(id)?opened.delete(id):opened.add(id);render()});document.querySelectorAll('[data-web-word]').forEach(b=>b.onclick=()=>guess(b.dataset.webWord))}
 return{render,normalize,accepts,result,webs};
})();
